function heading(title,desc,action='',symbol=''){return `<div class="page-heading"><div><div class="heading-title">${symbol?icon(symbol):''}<h1>${title}</h1></div><p>${desc}</p></div><div class="heading-actions">${action}</div></div>`;}
function tableProjects(){return `<div class="table-wrap"><table><thead><tr><th>项目</th><th class="num">当前 BOM</th><th>阶段</th><th>目标状态</th></tr></thead><tbody>${projects.map(p=>`<tr><td><button data-project="${p.code}">${p.code}</button><small>${p.name}</small></td><td class="num">¥${money(p.bom)}</td><td>${tag(p.stage)}</td><td>${tag(p.risk,p.risk==='已达标'?'green':p.goal?'amber':'gray')}</td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){return heading('今日工作台','今天优先处理影响降本的成本事项，让判断有据可循。','<span class="eyebrow">2026 / 09 / 06</span>','chart')+`<div class="dash-layout"><section class="focus-card"><span class="eyebrow">当前关注 / PDCP</span><h2>M27-Q</h2><p>27″ QHD 显示器 · 方案收敛</p><div class="glass-orbit" aria-label="目标差额10.50元，圆环为装饰"><div class="orbit-core"><small>待消除差额 / 元</small><strong>10<span>.50</span></strong></div></div><div class="focus-detail"><span>当前标准成本</span><b>¥640.50</b></div><div class="focus-detail"><span>财务目标</span><b>¥630.00</b></div><p class="focus-bottom">下一步先复核屏方案与驱动补偿。<br>当前版本：冻结 BOM v3</p><button class="button" data-project="M27-Q">继续项目${icon('arrow')}</button></section><div class="metrics">${[['project','进行中项目','4','个','4 个项目合计'],['risk','目标风险','1','项','另 1 个目标待确认'],['file','待审报价','1','项','包装范围待补齐'],['chart','已确认方案净节省','5.25','元/台','含平台费 · 尚未实施']].map(([i,l,v,u,d])=>`<section class="metric glass"><div class="metric-label"><span class="metric-icon">${icon(i)}</span>${l}</div><strong>${v}<small>${u}</small></strong><small>${d}</small></section>`).join('')}</div><section class="panel glass dash-projects"><div class="panel-head"><h2>项目成本进展</h2><button class="text-button" data-page="projects">全部项目${icon('arrow')}</button></div>${tableProjects()}</section><section class="panel glass task-panel"><div class="panel-head"><h2>今日优先处理</h2><span>3 项</span></div>${[['change','复核 M27-Q 的整包成本影响','节省与必要增本一起确认'],['quote','补齐第三家 ODM 报价条件','包装、附件与交付范围'],['target','确认 D27-C 的财务目标','目标未设定，不判为达标']].map(([d,t,s],i)=>`<button class="task-row" data-dialog="${d}"><span>${i+1}</span><span><b>${t}</b><small>${s}</small></span></button>`).join('')}<div class="task-note"><strong>机会成立，还需要实施证据</strong><p>净节省 ¥5.25 / 台，当前事实成本保持不变。</p></div></section><section class="panel glass cost-distribution"><div class="panel-head"><div><h2>项目成本分布</h2><p>当前 4 个项目 · 单台 BOM 成本，人民币</p></div><button class="text-button" data-page="projects">查看明细${icon('arrow')}</button></div><div class="chart-bars" role="img" aria-label="G32-U 1168元，D27-C 784元，M27-Q 610元，M24-F 385元">${[1168,784,610,385].map(n=>`<div class="chart-bar" style="--h:${n/12}px"><b>¥${money(n)}</b></div>`).join('')}</div><div class="chart-labels"><span>G32-U</span><span>D27-C</span><span>M27-Q</span><span>M24-F</span></div></section><section class="panel glass dash-signals"><div class="panel-head"><h2>报价决策抓手</h2><button class="text-button" data-page="intelligence">全部${icon('arrow')}</button></div><div class="quote-signal"><strong>27″ 显示模组 · 替代方案</strong><p>关联 CP–014，需连同驱动补偿评估。</p><b>−¥5.00</b> <small class="muted">BOM 净变化 / 台</small><br><button class="text-button" data-dialog="change">查看依赖与证据${icon('arrow')}</button></div></section></div>`;}
function projectContent(){const p=projects.find(p=>p.code===currentProject);if(projectTab==='quote')return `<section class="panel glass"><div class="panel-head"><div><h2>供应商整机报价</h2><p>CNY · 未税 · 1 台 · EXW · 产品规格 v3</p></div>${tag('同口径核对')}</div>${p.code==='M27-Q'?`<div class="table-wrap"><table><thead><tr><th>供应商</th><th class="num">整机报价</th><th>可比状态</th><th>来源</th></tr></thead><tbody><tr><td>ODM A</td><td class="num">¥672.00</td><td>${tag('条件已齐','green')}</td><td><button class="text-button" data-dialog="quote">原始报价</button></td></tr><tr><td>ODM B</td><td class="num">¥658.00</td><td>${tag('条件已齐','green')}</td><td><button class="text-button" data-dialog="quote">原始报价</button></td></tr><tr><td>ODM C</td><td class="num">待补齐</td><td>${tag('包装范围待确认','amber')}</td><td><button class="text-button" data-dialog="quote">查看缺项</button></td></tr></tbody></table></div>`:'<div class="empty">此项目的报价明细未在预览中展开。</div>'}</section>`;
if(projectTab==='history')return `<section class="panel glass"><div class="panel-head"><h2>版本档案</h2>${tag('只读事实')}</div>${p.code==='M27-Q'?`<div class="timeline-row"><span class="eyebrow">2026.09.05 / 14:32</span><h3>冻结 BOM v3</h3><p>产品规格 v3 · 平台费率 5% · 标准成本 ¥640.50</p><button class="text-button" data-dialog="version">打开来源快照${icon('arrow')}</button></div><div class="timeline-row"><span class="eyebrow">下一阶段</span><h3>等待新实施证据</h3><p>确认方案不会自动覆盖冻结成本。</p></div>`:'<div class="empty">本预览未展开该项目的版本档案。</div>'}</section>`;
return `<section class="panel glass project-cost"><div><div class="cost-caption">当前标准成本 · CNY / 台</div><div class="big-cost"><small>¥</small>${money(p.bom*1.05)}</div><div class="cost-caption">BOM ${money(p.bom)} + 平台费 ${money(p.bom*.05)} · 5%</div></div><div class="cost-compare"><div><span class="muted">财务目标</span><b>${p.goal?'¥'+money(p.goal):'待确认'}</b></div><div><span class="muted">与目标差额</span><b class="${p.goal&&p.bom*1.05>p.goal?'bad':'good'}">${p.goal?(p.bom*1.05>p.goal?'+':'−')+'¥'+money(Math.abs(p.bom*1.05-p.goal)):'—'}</b></div></div><div class="monitor-3d" aria-hidden="true"><div class="monitor-screen"><span>${p.code}</span></div><div class="monitor-stand"></div><div class="monitor-foot"></div></div></section>${p.code==='M27-Q'?`<div class="split"><section class="panel glass"><div class="panel-head"><div><h2>${projectTab==='measures'?'方案目标与净影响':'成本落在哪里'}</h2><p>未计平台费 · ¥ / 台 · 方案尚未实施</p></div></div><div class="table-wrap"><table><thead><tr><th>成本领域</th><th class="num">当前 BOM</th><th class="num">方案目标</th><th class="num">变化</th><th>依据</th></tr></thead><tbody>${domains.map(([n,c,t,s])=>`<tr><td>${n}</td><td class="num">${money(c)}</td><td class="num">${money(t)}</td><td class="num ${t<c?'good':''}">${t===c?'—':(t>c?'+':'−')+money(Math.abs(t-c))}</td><td><button class="text-button" data-dialog="${t===c?'version':'change'}">${s}</button></td></tr>`).join('')}<tr><td><b>合计</b></td><td class="num"><b>610.00</b></td><td class="num"><b>605.00</b></td><td class="num good"><b>−5.00</b></td><td></td></tr></tbody></table></div></section><aside class="panel glass decision">${tag('技术可行 · 尚未实施')}<h3>屏方案替代<br>及驱动补偿</h3><p>CP–014 · 必要依赖一起确认，金额一起守恒。</p><div class="delta-row"><span>显示模组替代</span><b class="good">−¥20.00</b></div><div class="delta-row"><span>驱动能力补偿</span><b>+¥15.00</b></div><div class="delta-row"><span>预计标准成本</span><b>¥635.25</b></div><p style="margin-top:13px">仍有 ¥5.25 缺口待覆盖。</p><button class="button" data-dialog="change">查看整包证据${icon('arrow')}</button></aside></div>`:`<section class="panel glass"><h2>成本来源</h2><p class="muted" style="margin-top:12px">已展示该项目的汇总示例。领域明细在正式接入时读取该项目自身来源，预览不复用 M27-Q 的明细。</p></section>`}`;}
function projectPage(){const p=projects.find(p=>p.code===currentProject);return heading('项目','让规格、报价与决策，落在同一个项目里。',`<button class="button" data-dialog="package">${icon('file')}阶段成本包</button>`,'project')+`<div class="project-shell"><aside class="panel glass project-index"><h2>项目档案 · 4</h2>${projects.map(x=>`<button class="project-item ${x.code===p.code?'active':''}" data-project="${x.code}" aria-pressed="${x.code===p.code}"><strong>${x.code}</strong><small>${x.name}</small><small>${x.stage} · ${x.risk}</small></button>`).join('')}</aside><div><div class="panel-head"><div><h2 style="font-size:22px">${p.code} <span style="font-size:13px;font-weight:400;color:#7585a1">${p.name}</span></h2><p>${p.spec}</p></div>${tag(p.stage)}</div><div class="tabs" role="tablist" aria-label="项目工作区">${[['overview','项目总览'],['quote','BOM 与报价'],['measures','目标与措施'],['history','版本档案']].map(([k,n])=>`<button role="tab" aria-selected="${projectTab===k}" class="${projectTab===k?'active':''}" data-project-tab="${k}">${n}</button>`).join('')}<span class="right-meta">产品规格 v3</span></div><div id="project-content">${projectContent()}</div></div></div>`;}
